#include <vector>
#include <algorithm>
#include <omp.h>

/* Compute the reverse prefix (suffix) sum of the vector x into output.
   The result at position i is  sum_{j=i}^{n-1} x[j].
   The implementation works correctly for any number of OpenMP threads.
*/
void reversePrefixSum(const std::vector<int>& x, std::vector<int>& output)
{
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    const int max_threads = omp_get_max_threads();

    /* 1st parallel region:
       * each thread works on a contiguous chunk,
       * computes the suffix sums *inside* its chunk (right‑to‑left),
       * and stores the total sum of its chunk in block_sum[tid].
    */
    std::vector<int> block_sum(max_threads, 0);
    #pragma omp parallel
    {
        const int tid      = omp_get_thread_num();
        const int nthreads = omp_get_num_threads();

        // contiguous chunk for this thread (ceil division)
        const std::size_t chunk = (n + nthreads - 1) / nthreads;
        const std::size_t start = tid * chunk;
        const std::size_t end   = std::min(start + chunk, n);   // exclusive

        int local_sum = 0;
        // walk backwards inside the chunk
        for (std::size_t i = end; i-- > start; ) {
            local_sum += x[i];
            output[i] = local_sum;          // suffix sum limited to this chunk
        }
        block_sum[tid] = local_sum;          // total of the whole chunk
    }

    /* 2nd step: compute the offset that each chunk must add.
       offset[t] = sum of all block_sum of chunks with index > t.
       This can be done sequentially because the number of chunks
       equals the number of threads (typically small) and the result
       is needed before the next parallel region.
    */
    std::vector<int> block_offset(max_threads, 0);
    for (int t = max_threads - 2; t >= 0; --t) {
        block_offset[t] = block_offset[t + 1] + block_sum[t + 1];
    }

    /* 3rd parallel region:
       * each thread adds its pre‑computed offset to every element
       * of its chunk, turning the local suffix sums into global ones.
       */
    #pragma omp parallel
    {
        const int tid      = omp_get_thread_num();
        const int nthreads = omp_get_num_threads();

        const std::size_t chunk = (n + nthreads - 1) / nthreads;
        const std::size_t start = tid * chunk;
        const std::size_t end   = std::min(start + chunk, n);   // exclusive

        const int offset = block_offset[tid];
        for (std::size_t i = start; i < end; ++i) {
            output[i] += offset;
        }
    }
}
