*/
void reversePrefixSum(const std::vector<int>& x, std::vector<int>& output)
{
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    /* Disable dynamic adjustment of the thread team so that the
       number of threads stays the same across the two parallel regions. */
    omp_set_dynamic(0);

    const int max_threads = omp_get_max_threads();   // upper bound on threads
    std::vector<int> block_sum(max_threads, 0);      // sum of each chunk
    std::vector<int> block_offset(max_threads, 0);   // offset to add later

    /* --------------------------------------------------------------
       First parallel region:
       * each thread processes a contiguous chunk (static schedule)
       * walks backwards inside its chunk, producing a *local* suffix sum
       * and stores the total of its chunk in block_sum[tid].
       -------------------------------------------------------------- */
    #pragma omp parallel num_threads(max_threads) shared(block_sum, output)
    {
        const int tid      = omp_get_thread_num();
        const int nthreads = omp_get_num_threads();

        // Compute chunk boundaries (ceil division)
        const std::size_t chunk = (n + nthreads - 1) / nthreads;
        const std::size_t start = tid * chunk;
        const std::size_t end   = std::min(start + chunk, n);   // exclusive

        int local_sum = 0;
        // Walk right‑to‑left inside the chunk
        for (std::size_t i = end; i-- > start; ) {
            local_sum += x[i];
            output[i] = local_sum;          // local suffix sum (within chunk)
        }
        block_sum[tid] = local_sum;          // total of the whole chunk
    }   // implicit barrier guarantees block_sum is fully populated

    /* --------------------------------------------------------------
       Compute the offset each chunk must add.
       offset[t] = sum of block_sum of all chunks with index > t.
       This step is sequential but cheap (max_threads is small).
       -------------------------------------------------------------- */
    for (int t = max_threads - 2; t >= 0; --t) {
        block_offset[t] = block_offset[t + 1] + block_sum[t + 1];
    }

    /* --------------------------------------------------------------
       Second parallel region:
       * each thread adds its pre‑computed offset to every element
       * of its chunk, turning the local suffix sums into the final
       * global suffix sums.
       -------------------------------------------------------------- */
    #pragma omp parallel num_threads(max_threads) shared(block_offset, output)
    {
        const int tid      = omp_get_thread_num();
        const int nthreads = omp_get_num_threads();

        const std::size_t chunk = (n + nthreads - 1) / nthreads;
        const std::size_t start = tid * chunk;
        const std::size_t end   = std::min(start + chunk, n);   // exclusive

        const int offset = block_offset[tid];
        for (std::size_t i = start; i < end; ++i) {
            output[i] += offset;
        }
    }   // implicit barrier; all writes are finished
}
